el>Payment account<select name="bank_account_id"><option value="">No account selected</option><?php foreach($banks as $bank):?><option value="<?= e($bank['id']) ?>" <?= ($editing['bank_account_id']??'')===$bank['id']?'selected':'' ?>><?= e($bank['bank_name'].' · '.$bank['currency'].' · '.$bank['account_number']) ?></option><?php endforeach;?></select></label></div><h2>Line items</h2><div class="line-item-editor" data-line-items><?php $itemRows=$editing['items']??[[]];foreach($itemRows as $item):commercial_item_row($item);endforeach;?></div><button type="button" class="secondary" data-add-line>+ Add line item</button><div class="document-totals" data-builder-totals></div><div class="form-grid"><label>Payment terms<textarea name="payment_terms"><?= e($editing['payment_terms']??$profile['default_payment_terms']) ?></textarea></label><label>Delivery terms<textarea name="delivery_terms"><?= e($editing['delivery_terms']??'') ?></textarea></label><label>Lead time<input name="lead_time" value="<?= e($editing['lead_time']??'') ?>"></label><label>Adjustment<input type="number" step="0.01" name="adjustment_total" value="<?= e((string)($editing['adjustment_total']??0)) ?>"></label><label class="full">Notes<textarea name="notes"><?= e($editing['notes']??'') ?></textarea></label></div><button class="primary">Save draft</button></form><?php endif;?>
<?php elseif($view==='document'):$events=rows('SELECT e.*,u.full_name FROM commercial_document_events e LEFT JOIN users u ON u.id=e.actor_user_id WHERE e.document_id=? ORDER BY e.created_at DESC',[$document['id']]);?><section class="page-heading"><div><p class="eyebrow"><?= e($document['document_type']) ?></p><h1><?= e($document['document_number']) ?></h1><p><?= e($document['customer_name'].' · '.$document['currency'].' '.number_format((float)$document['grand_total'],2)) ?></p></div><div class="page-actions"><?php if($document['status']==='DRAFT'):?><a class="secondary" href="commercial?view=create&id=<?= e($document['id']) ?>&type=<?= e($document['document_type']) ?>">Edit draft</a><form action="commercial-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="document.issue"><input type="hidden" name="id" value="<?= e($document['id']) ?>"><button class="primary">Issue document</button></form><?php endif;?><?php if($document['document_type']==='QUOTATION'&&in_array($document['status'],['ISSUED','ACCEPTED'],true)):?><form action="commercial-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="quote.convert"><input type="hidden" name="id" value="<?= e($document['id']) ?>"><button class="primary">Convert to invoice</button></form><?php endif;?><a class="secondary" target="_blank" href="commercial-document?id=<?= e($document['id']) ?>">Preview / Print</a><a class="secondary" href="commercial-document?id=<?= e($document['id']) ?>&download=1">Download PDF</a></div></section><section class="panel commercial-document-summary"><span class="request-badge"><?= e($document['status']) ?></span><h2>Line items</h2><table><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Duration</th><th>Rate</th><th>Total</th></tr></thead><tbody><?php foreach($document['items'] as $item):?><tr><td><?= e($item['description']) ?></td><td><?= e($item['quantity']) ?></td><td><?= e($item['unit']) ?></td><td><?= e($item['duration']) ?></td><td><?= number_format((float)$item['rate'],2) ?></td><td><?= number_format((float)$item['total_amount'],2) ?></td></tr><?php endforeach;?></tbody></table><div class="document-totals"><span>Subtotal <strong><?= number_format((float)$document['subtotal'],2) ?></strong></span><span>Discount <strong><?= number_format((float)$document['discount_total'],2) ?></strong></span><span>Tax <strong><?= number_format((float)$document['tax_total'],2) ?></strong></span><span>Total <strong><?= e($document['currency'].' '.number_format((float)$document['grand_total'],2)) ?></strong></span></div></section><section class="panel commercial-panel"><div class="panel-heading"><h2>Document history</h2></div><div class="commercial-list"><?php foreach($events as $event):?><div><strong><?= e(str_replace('_',' ',$event['event_type'])) ?></strong><span><?= e(($event['full_name']??'System').' · '.$event['created_at']) ?></span></div><?php endforeach;?></div></section>
<?php else:$tax=rows("SELECT d.document_number,c.name customer_name,c.tin,t.vat_amount,t.expected_wht,t.wht_status FROM commercial_documents d JOIN commercial_customers c ON c.id=d.customer_id LEFT JOIN commercial_tax_records t ON t.invoice_id=d.id WHERE d.organization_id=? AND d.document_type='INVOICE' ORDER BY d.issue_date DESC",[$user['owner_id']]);?><section class="page-heading"><div><p class="eyebrow">COMMERCIAL</p><h1>Tax & WHT</h1><p>Invoice tax visibility without blocking document creation.</p></div></section><section class="panel commercial-panel"><table><thead><tr><th>Invoice</th><th>Customer</th><th>TIN</th><th>VAT</th><th>Expected WHT</th><th>WHT status</th></tr></thead><tbody><?php foreach($tax as $row):?><tr><td><?= e($row['document_number']) ?></td><td><?= e($row['customer_name']) ?></td><td><?= e($row['tin']?:'Missing') ?></td><td><?= number_format((float)($row['vat_amount']??0),2) ?></td><td><?= number_format((float)($row['expected_wht']??0),2) ?></td><td><?= e($row['wht_status']??'NOT APPLICABLE') ?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
<?php require __DIR__.'/includes/operations-footer.php';
function commercial_table(array $documents):void{?><div class="market-table-wrap"><table><thead><tr><th>Number</th><th>Customer</th><th>Date</th><th>Due / Valid</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($documents as $document):?><tr><td><strong><?= e($document['document_number']) ?></strong></td><td><?= e($document['customer_name']) ?></td><td><?= e($document['issue_date']) ?></td><td><?= e($document['due_date']?:$document['valid_until']?:'—') ?></td><td><?= e($document['currency'].' '.number_format((float)$document['grand_total'],2)) ?></td><td><span class="request-badge"><?= e($document['status']) ?></span></td><td><a href="commercial?view=document&id=<?= e($document['id']) ?>">Open</a></td></tr><?php endforeach;?></tbody></table></div><?php }
function commercial_item_row(array $item=[]):void{?><div class="line-item-row"><textarea name="item_description[]" placeholder="Description" required><?= e($item['description']??'') ?></textarea><input type="number" step="0.001" min="0" name="item_quantity[]" value="<?= e((string)($item['quantity']??1)) ?>" aria-label="Quantity"><select name="item_unit[]"><?php foreach(['Each','Unit','Hour','Day','Week','Month','Job','Lot','Service','Meter','Kg','Tonne','Custom'] as $unit):?><option <?= ($item['unit']??'Each')===$unit?'selected':'' ?>><?= $unit ?></option><?php endforeach;?></select><input type="number" step="0.001" min="0" name="item_duration[]" value="<?= e((string)($item['duration']??1)) ?>" aria-label="Duration"><input type="number" step="0.01" min="0" name="item_rate[]" value="<?= e((string)($item['rate']??0)) ?>" aria-label="Rate"><input type="number" step="0.001" min="0" max="100" name="item_discount[]" value="<?= e((string)($item['discount_rate']??0)) ?>" aria-label="Discount percent"><input type="number" step="0.001" min="0" max="100" name="item_tax[]" value="<?= e((string)($item['tax_rate']??0)) ?>" aria-label="Tax percent"><output>0.00</output><button type="button" data-remove-line aria-label="Remove line">×</button></div><?php }
